    "settings.classifier.offAbout": "No consulta a nadie para juzgar la dificultad. Los modelos se eligen por el veredicto de palabras clave.",
    "settings.classifier.probedAbout": "También consulta una vez al modelo rápido del proveedor de esta sesión (unos 200 tokens de salida). Si tarda o falla, vale el veredicto por palabras clave.",
