    "settings.harness.alerts": "Avisos del libro: integraciones tardías y ramas atrasadas",
    "settings.harness.alertsHint": "Si se activa, el libro compara cada minuto los registros de trabajo con git. Avisa al coordinador del run si hay informes sin verificar tras más de 2 horas, trabajo verificado sin registro de fusión o fusionado con la carpeta sin limpiar; avisa al worker si su rama va muy por detrás de main o chocaría al fusionar. Solo avisa: no fusiona, no borra ni hace push.",
    "settings.harness.alertsOn": "Activado",
    "settings.harness.alertsOff": "Desactivado",
    "settings.harness.prompts": "Cuando un trabajador convocado pide permiso",
    "settings.harness.promptsHint": "«Preguntar» mantiene el comportamiento actual: el trabajador espera en el aviso de permiso la respuesta de una persona. Con «Rechazar y seguir», esa llamada se rechaza al instante, se le dice al modelo y continúa el turno; varios rechazos seguidos terminan el turno. Se rechaza una acción que quizá habrías permitido y, a cambio, el trabajador nunca se queda parado. La ventana lanza los trabajadores para que no se detengan a preguntar, así que la mayoría de los agentes, Codex y zo entre ellos, nunca abren un aviso de permiso; este ajuste alcanza a los trabajadores de Claude Code que aun así preguntan (Claude Code 2.1.319 o posterior). Los paneles que abres tú no cambian, y un trabajador ya en marcha lo sigue desde su próximo inicio.",
    "settings.harness.promptsAsk": "Preguntar",
    "settings.harness.promptsRefuse": "Rechazar y seguir",
    "settings.harness.peerMail": "Cartas entre paneles de agentes",
    "settings.harness.peerMailHint": "Si se activa, los paneles de agentes que abres en esta ventana pueden enviar cartas del libro a otros paneles del mismo proyecto; los paneles se encuentran con zerocode-orc peers. Una carta despierta un panel como mucho tres veces desde la última vez que escribiste en él, y una respuesta no despierta a nadie. No se puede escribir a un panel de otro proyecto, y una carta para un worker va al coordinador de su run. Si se desactiva, las cartas nuevas se rechazan y las ya enviadas se pueden leer.",
