    "computerUse.accessibilityHint": "En Ajustes del Sistema → Privacidad y seguridad → Accesibilidad, activa {{row}}. Si no aparece, usa + para añadir {{path}}. Si ya está activado pero sigue sin permiso, restablece el permiso, actívalo y comprueba de nuevo.",
    "computerUse.screenshotsHint": "En Ajustes del Sistema → Privacidad y seguridad → Grabación de pantalla y audio del sistema, activa {{row}}. Si no aparece, usa + para añadir {{path}}. Si ya está activado pero sigue sin permiso, restablece el permiso, actívalo y comprueba de nuevo.",
