    "computerUse.shareRequired": "Exigir compartir la ventana",
    "computerUse.shareRequiredAbout": "Bloquea las acciones en aplicaciones que no se hayan compartido. El silencio no permite actuar. La visualización mantiene las reglas actuales.",
    "computerUse.deskGuard": "Impedir que zo mueva la pantalla con comandos de shell",
    "computerUse.deskGuardAbout": "En los paneles de zo de esta ventana, cuando el modelo envía un comando de shell que mueve la pantalla directamente —cliclick o un script de System Events, por ejemplo—, zo lo rechaza en cualquier modo de permisos y devuelve al modelo a la herramienta Computer. Solo lo detecta cuando ese nombre aparece en el texto del comando, y no se aplica a los paneles de Claude Code ni de Codex. El cambio se aplica a las sesiones de zo que inicies después; una sesión ya en marcha puede seguir usando el valor que leyó.",
    "computerUse.deskGuardUnreadable": "No se pudo leer el archivo de ajustes de zo, así que no se sabe si esto está activado. Corrige el archivo y vuelve a abrir esta página.",
    "computerUse.deskGuardNotBoolean": "deskGuard en el archivo de ajustes de zo no es true ni false, así que no se sabe si esto está activado. Corrige esa línea en el archivo o elimínala.",
    "computerUse.inputPolicyTitle": "Trabajar en segundo plano",
    "computerUse.inputPolicyAbout": "La entrada en segundo plano es la predeterminada. Las acciones no compatibles se detienen sin pasar al primer plano. Aunque actives la opción siguiente, nada los toma por su cuenta: un agente usa tu ratón, teclado y foco solo cuando lo indica, en el trabajo que pediste.",
