    "computerUse.liveReflex": "Capa de reflejos en tiempo real",
    "computerUse.liveReflexAbout": "En pantallas rápidas, como los juegos, cuando un agente inicia un plan de reflejos el asistente mira la pantalla directamente y pulsa según el plan. Encendida, solo ayuda mientras corre un plan. Apagada por defecto.",
