    "computerUse.generator": "Escribir en campos · planes del piloto automático",
    "computerUse.generatorAbout": "Cuando un agente encuentra un campo vacío, o el piloto automático reflejo escribe un plan, se pregunta a un modelo pequeño. Por defecto es el inicio de sesión con el que esta ventana abre sus agentes: se ejecuta una vez la CLI oficial y se gasta el límite de la suscripción de esa cuenta; el inicio de sesión nunca se lee ni se envía. Un valor que ya está en el campo nunca se envía.",
