    "computer.handoff.codeHint": "De {{min}} a {{max}} letras o dígitos · la ventana lo escribe una vez en el campo que indicó el agente; el agente no lo recibe",
    "computer.handoff.codeSend": "Enviar",
    "computer.handoff.codeInvalid": "Escribe de {{min}} a {{max}} letras o dígitos",
    "emulator.realPhone.consent": "Un agente pide controlar el teléfono real «{{phone}}» desde dentro. Si lo permites, se compila en este Mac Appium WebDriverAgent {{tag}} con un pequeño parche nuestro (una versión modificada) y se instala en el teléfono firmado por el equipo «{{team}}» ({{kind}}). Xcode crea un App ID y un perfil de aprovisionamiento para este runner en tu cuenta de Apple. Después los agentes podrán leer la pantalla, pulsar y escribir sin el puntero del Mac, incluso mientras usas el teléfono; bloquéalo para detenerlos. Nunca lo desbloquean ni escriben contraseñas; pagos y transferencias siguen siendo tuyos. Dura para este teléfono hasta que lo apagues en Ajustes o ejecutes phone-remove. Para permitirlo, pulsa Listo.",
    "emulator.realPhone.remove": "Un agente pide quitar WebDriverAgent de «{{phone}}» y su compilación de este Mac, y apagar el control de teléfonos reales. Nada más cambia en el teléfono. El App ID y el perfil que Xcode creó en tu cuenta de Apple se quedan. Para permitirlo, pulsa Listo.",
    "emulator.realPhone.androidConsent": "Un agente pide controlar el teléfono Android real “{{phone}}” por depuración USB o inalámbrica (adb). Al permitirlo se copia un pequeño asistente de texto nuestro en /data/local/tmp del teléfono para escribir en cualquier idioma; no se instala ninguna app. Después los agentes pueden leer la pantalla, pulsar, deslizar y escribir en este teléfono sin el puntero del Mac, incluso mientras lo usas; bloquéalo para detenerlos. Nunca lo desbloquean, pulsan su botón de encendido, cambian sus ajustes, instalan o quitan apps ni escriben una contraseña; un pago o una transferencia siguen siendo tuyos. Dura para este teléfono hasta que lo desactives en Ajustes o ejecutes phone-remove. Para permitirlo, pulsa Listo.",
    "emulator.realPhone.androidRemove": "Un agente pide quitar el asistente de texto de esta ventana del teléfono Android “{{phone}}” y dejar de controlarlo. Nada más cambia en el teléfono. Para permitirlo, pulsa Listo.",
    "emulator.realPhone.title": "Control del teléfono real",
    "emulator.realPhone.about": "Los agentes controlan el teléfono con un WebDriverAgent modificado dentro de él, sin el puntero del Mac. Solo tú puedes activarlo, teléfono por teléfono, en la tarjeta del primer uso. Los agentes pueden pulsar incluso mientras usas el teléfono; bloquéalo para detenerlos. Desbloqueo, contraseñas, pagos y transferencias son siempre tuyos. La compilación crea un App ID y un perfil para este runner en tu cuenta de Apple. Un teléfono Android se controla por depuración USB sin compilar nada: al permitirlo se copia un pequeño asistente de texto en su /data/local/tmp, y los agentes nunca tocan su botón de encendido, sus ajustes ni sus apps.",
    "emulator.realPhone.allowed": "Permitido (al apagarlo termina el runner)",
    "emulator.realPhone.allowedOff": "Se activa desde la tarjeta que muestra un agente la primera vez que usa el teléfono.",
    "emulator.realPhone.unattended": "Uso desatendido (mantener el runner sin uso y reiniciarlo si muere)",
    "emulator.realPhone.removeAll": "Quitar",
    "emulator.realPhone.removeAllHint": "Lo apaga y quita la app del runner de los teléfonos conectados y las compilaciones de este Mac. El App ID y el perfil de tu cuenta de Apple se quedan.",
    "computer.cover.ask": "Se detuvo: una ventana de «{{app}}» tapa el lugar que hay que pulsar. No se leyó ni se cerró. Despéjalo tú y pulsa Listo.",
    "computer.cover.stuck": "La ventana se trajo al frente y se apartó, pero una ventana de «{{app}}» sigue tapando el lugar que hay que pulsar. Despéjalo tú y pulsa Listo.",
    "computer.cover.gone": "La ventana donde había que pulsar no está en la pantalla (minimizada o en otro escritorio). Muéstrala y pulsa Listo.",
